import React, {
  useImperativeHandle,
  useRef,
  useState,
  forwardRef,
} from 'react';
import {View, Platform} from 'react-native';
import {actions, RichEditor, RichToolbar} from 'react-native-pell-rich-editor';
import {
  handleBullet,
  handleHead,
  handleHeadH2,
  handleHeadH3,
  handleLink,
  handleOrder,
  handleRedo,
  handleSetBold,
  handleSetItalic,
  handleSetUnderline,
  handleUndo,
} from '../../screens/task-detail/components/task-detail-screen/component/modal-description/helper';
import {useTranslation} from 'react-i18next';
import styles from './styles';

type InputRichTextProps = {
  initialValue?: string;
  placeholder?: string;
  onChange?: (value: string) => void;
  onBlur?: (value: string) => void;
  containerStyle?: object;
  editorStyle?: object;
  toolbarStyle?: object;
};

export type InputRichTextRef = {
  focus: () => void;
  blur: () => void;
  
  setContent: () => void;
};

const InputRichText = forwardRef<InputRichTextRef, InputRichTextProps>(
  (
    {
      initialValue = '',
      onChange,
      containerStyle,
      editorStyle,
      onBlur,
      toolbarStyle,
    },
    ref,
  ) => {
    const {t} = useTranslation();
    const [showToolbar, setShowToolbar] = useState(false);
    const [text, setText] = useState(initialValue);
    const editorRef = useRef<RichEditor>(null);

    useImperativeHandle(ref, () => ({
      focus: () => editorRef.current?.focusContentEditor?.(),
      blur: () => {
        editorRef.current?.blurContentEditor?.();        
    },
      setContent: () => {editorRef.current?.setContentHTML('');},
    }));

    return (
      <View style={containerStyle}>
        {showToolbar && (
          <View style={[styles.toolbarContainer, toolbarStyle]}>
            <RichToolbar
              editor={editorRef}
              actions={[
                actions.setBold,
                actions.setItalic,
                actions.setUnderline,
                actions.insertBulletsList,
                actions.insertOrderedList,
                actions.heading1,
                actions.heading2,
                actions.heading3,
                actions.insertLink,
                actions.undo,
                actions.redo,
              ]}
              iconMap={
                Platform.OS === 'ios'
                  ? {
                      [actions.setBold]: handleSetBold,
                      [actions.setItalic]: handleSetItalic,
                      [actions.setUnderline]: handleSetUnderline,
                      [actions.insertBulletsList]: handleBullet,
                      [actions.insertOrderedList]: handleOrder,
                      [actions.heading1]: handleHead,
                      [actions.heading2]: handleHeadH2,
                      [actions.heading3]: handleHeadH3,
                      [actions.insertLink]: handleLink,
                      [actions.undo]: handleUndo,
                      [actions.redo]: handleRedo,
                    }
                  : {
                      [actions.heading1]: handleHead,
                      [actions.heading2]: handleHeadH2,
                      [actions.heading3]: handleHeadH3,
                    }
              }
              iconTint="#000"
              selectedIconTint="#2095F2"
              style={styles.toolbar}
            />
          </View>
        )}

        <RichEditor
          ref={editorRef}
          initialContentHTML={text}
          style={[{minWidth: 150}, editorStyle]}
          editorStyle={{backgroundColor: 'transparent'}}
          placeholder={t('task.enter-content') + '...'}
          onFocus={() => {
            setShowToolbar(true);
          }}
          onChange={content => {
            setText(content);
            onChange?.(content);
          }}
          onBlur={() => {
            setShowToolbar(false);
            onBlur?.(text);
          }}
        />
      </View>
    );
  },
);

export default InputRichText;
