import {Button, Icon, MenuItem, OverflowMenu} from '@ui-kitten/components';
import {
  FlatList,
  Keyboard,
  KeyboardAvoidingView,
  Platform,
  Pressable,
  TouchableOpacity,
  TouchableWithoutFeedback,
  View,
} from 'react-native';
import TextCM from '../../../../../../components/Text';
import styles from './styles';
import {IComment, ITaskActivities} from '../../../../helper';
import {useTranslation} from 'react-i18next';
import {useAppSelector} from '../../../../../../../hooks/useRedux';
import {DateUtils} from '../../../../../../../utils';
import RenderHtml from 'react-native-render-html';
import {stylesHTML} from '../../../../../notification/NotificationCard/helper';
import {useBoardService} from '../../../../../../../hooks/apiHooks/useAPI';
import {useRef, useState} from 'react';
import ButtonCM from '../../../../../../components/Button';
import ModalConfirmCM from '../../../../../../components/ModalConfirm';
import {Color} from '../../../../../../../constants';
import Toast from 'react-native-toast-message';
import InputRichText, {
  InputRichTextRef,
} from '../../../../../../components/InputRichToolBar';
import {RichEditor} from 'react-native-pell-rich-editor';
import {KeyboardAwareFlatList} from 'react-native-keyboard-aware-scroll-view';

type Props = {
  taskActivities?: ITaskActivities[];
  taskId?: string;
  listComment?: IComment[] | null;
  setListComment?: React.Dispatch<React.SetStateAction<IComment[] | null>>;
  onReply?: (createdBy: string, commentId: string) => void;
};

interface TimelineItem {
  type: 'activity' | 'comment';
  data: ITaskActivities | IComment;
  createdDate: string;
  level?: number;
  isLast?: boolean;
}

const ActivitiesScreen = ({
  taskActivities,
  taskId,
  onReply,
  listComment,
  setListComment,
}: Props) => {
  const {t} = useTranslation();
  const {dataAccount} = useAppSelector(state => state.account);
  const [visible, setVisible] = useState<string | null>(null);
  const [editingCommentId, setEditingCommentId] = useState<string | null>(null);
  const [editingText, setEditingText] = useState('');
  const [confirmDeleteVisible, setConfirmDeleteVisible] = useState(false);
  const editorRef = useRef<InputRichTextRef>(null);
  const BoardService = useBoardService();

  const getTimelineItems = (): TimelineItem[] => {
    const activities: TimelineItem[] =
      taskActivities?.map(item => ({
        type: 'activity',
        data: item,
        createdDate: item.createdDate,
      })) || [];

    const rootComments: TimelineItem[] =
      listComment
        ?.filter(c => !c.commentIn)
        .map(item => ({
          type: 'comment',
          data: item,
          createdDate: item.createdDate,
          level: 0,
          isLast: isLastInBranch(
            item,
            listComment?.filter(c => !c.commentIn) || [],
            0,
          ),
        })) || [];

    return [...activities, ...rootComments].sort(
      (a, b) =>
        new Date(a.createdDate).getTime() - new Date(b.createdDate).getTime(),
    );
  };

  const getContentHistory = (taskHis: ITaskActivities) => {
    let oldValue: string = '',
      newValue: string = '';
    if (taskHis.actionCode === 'CHG_TSK') {
      if (
        taskHis.param.oldStatus !== 'processing' &&
        taskHis.param.oldStatus !== 'todo' &&
        taskHis.param.oldStatus !== 'completed' &&
        taskHis.param.oldStatus !== 'approved'
      ) {
        oldValue = taskHis.param.oldStatus || '';
      } else {
        oldValue = t('board.status-' + taskHis.param.oldStatus);
      }

      if (
        taskHis.param.newStatus !== 'processing' &&
        taskHis.param.newStatus !== 'todo' &&
        taskHis.param.newStatus !== 'completed' &&
        taskHis.param.newStatus !== 'approved'
      ) {
        newValue = taskHis.param.newStatus || '';
      } else {
        newValue = t('board.status-' + taskHis.param.newStatus);
      }
    }
    const createdBy =
      taskHis.createdBy !== dataAccount.email
        ? t('task.you')
        : taskHis.createdBy;
    return t(`task.private.${taskHis.actionCode}`, {
      name: taskHis.taskName,
      createdBy,
      oldValue,
      newValue,
      style: stylesHTML.RED_BOLD,
    });
  };

  const updateComment = async () => {
    try {
      if (!taskId) return;
      const bodyUpdate = listComment
        ?.map(item => {
          if (item.id === editingCommentId) {
            return {
              ...item,
              name: editingText,
            };
          }
          if (item.commentIn === editingCommentId) {
            return {
              ...item,
              status: 'sent',
              taskId: taskId,
              users: [],
            };
          }
          return undefined;
        })
        .filter(Boolean);

      let body = null;
      if (!bodyUpdate) return;
      if (bodyUpdate.length > 0) {
        const [first, ...rest] = bodyUpdate;
        body = {
          ...first,
          children: rest,
          status: 'editting',
        };
      }
      if (body) {
        const data = await BoardService.updateComment(body);
        if (data) {
          setListComment?.(prevList => {
            if (!prevList) return [data];
            return prevList.map(c => (c.id === data.id ? data : c));
          });
          setEditingCommentId(null);
        }
      }
    } catch (error) {
      console.log('error', error);
    }
  };

  const handleConfirmDelete = async () => {
    try {
      if (editingCommentId) {
        const res = await BoardService.deleteComment(editingCommentId);
        if (res) {
          setConfirmDeleteVisible(false);
          setListComment?.(
            prevList =>
              prevList?.filter(c => c.id !== editingCommentId) || null,
          );
          setEditingCommentId(null);
          Toast.show({
            type: 'success',
            text1: t('CM.noti'),
            text2: t('task.success-delete-cmt'),
          });
        } else {
          console.log('Xóa thất bại, phản hồi không mong đợi:', res);
        }
      }
    } catch (error) {
      console.log('Delete error:', error);
    }
  };

  const isLastInBranch = (
    comment: IComment,
    comments: IComment[],
    index: number,
  ): boolean => {
    const childComments = comments.filter(c => c.commentIn === comment.id);
    if (childComments.length > 0) {
      return false;
    }
    return index === comments.length - 1;
  };

  const renderComment = (
    comment: IComment,
    level = 0,
    parentComments: IComment[] = [],
    index: number = 0,
  ) => {
    const isCurrentUser = comment.createdBy !== dataAccount.email;
    const createdBy = isCurrentUser ? t('task.you') : comment.createdBy;
    const createByMe = isCurrentUser ? t('task.yourself') : comment.createdBy;
    const createdAt = DateUtils.convertDateToDDMMYYYY_H_M(comment.createdDate);
    const isEditing = editingCommentId === comment.id;

    const childComments =
      listComment?.filter(c => c.commentIn === comment.id) || [];
    const isLast = isLastInBranch(
      comment,
      parentComments.length > 0
        ? parentComments
        : listComment?.filter(c => !c.commentIn) || [],
      index,
    );

    return (
      <View key={comment.id} style={{marginTop: 12}}>
        <View style={{flexDirection: 'row'}}>
          {level > 0 && <View style={styles.connerBlock}></View>}
          {level >= 1 && !isLast && <View style={styles.verticalBlock}></View>}
          {level === 0 && childComments.length > 0 && (
            <View style={styles.inserVertical} />
          )}
          <View style={[styles.container, {flex: 1}]}>
            <View style={{padding: 12}}>
              <View style={styles.headerFirst}>
                <TextCM style={isCurrentUser && styles.currentUser}>
                  {createdBy} <TextCM>{t('task.commented')}</TextCM>
                </TextCM>
                <OverflowMenu
                  anchor={() => (
                    <Pressable onPress={() => setVisible(comment.id)}>
                      <Icon
                        name="more-horizontal-outline"
                        fill="#8F9BB3"
                        style={styles.icon}
                      />
                    </Pressable>
                  )}
                  visible={visible === comment.id}
                  onBackdropPress={() => setVisible(null)}>
                  <MenuItem
                    title={() => (
                      <View style={styles.menuItem}>
                        <Icon name="edit-outline" style={styles.icon} />
                        <TextCM>{t('task.edit-cmt')}</TextCM>
                      </View>
                    )}
                    onPress={() => {
                      setEditingCommentId(comment.id);
                      setEditingText(comment.name);
                      setVisible(null);
                    }}
                  />

                  <MenuItem
                    title={() => (
                      <View style={styles.menuItem}>
                        <Icon
                          name="trash-outline"
                          style={styles.icon}
                          fill="#CA1E66"
                        />
                        <TextCM style={{color: '#CA1E66'}}>
                          {t('task.delete-cmt')}
                        </TextCM>
                      </View>
                    )}
                    onPress={() => {
                      setEditingCommentId(comment.id);
                      setConfirmDeleteVisible(true);
                    }}
                  />
                </OverflowMenu>
              </View>
              <TextCM style={styles.time}>{createdAt}</TextCM>
              <ModalConfirmCM
                type="cancel"
                isVisible={confirmDeleteVisible}
                onClose={() => setConfirmDeleteVisible(false)}
                title={t('task.delete-cmt')}
                content={t('task.delete-cmt-1')}
                onConfirm={handleConfirmDelete}
                styleBtnRight={{backgroundColor: Color.RedE14337}}
                labelCancel={t('task.button.cancel')}
                labelConfirm={t('task.button.confirm')}
              />
            </View>
            <View>
              {isEditing ? (
                <View>
                  <InputRichText
                    ref={editorRef}
                    initialValue={editingText}
                    onChange={setEditingText}
                    containerStyle={styles.inputRich}
                  />

                  <View style={styles.bottomEdit}>
                    <Button
                      status="basic"
                      onPress={() => setEditingCommentId(null)}>
                      {t('task.button.cancel')}
                    </Button>
                    <ButtonCM
                      onPress={() => {
                        updateComment();
                      }}
                      style={{backgroundColor: '#CA1E66'}}
                      label={t('task.button.save')}
                    />
                  </View>
                </View>
              ) : (
                <View>
                  <View style={{paddingHorizontal: 12, paddingTop: 0}}>
                    <RenderHtml
                      source={{html: comment.name}}
                      baseFontStyle={{ color: 'black' }}
                    />
                  </View>
                  <TouchableOpacity
                    onPress={() => {
                      const replyId = comment.commentIn ?? comment.id;
                      onReply?.(createByMe, replyId);
                    }}
                    style={styles.replyBtn}>
                    <TextCM style={styles.replyText}>{t('task.reply')}</TextCM>
                  </TouchableOpacity>
                </View>
              )}
            </View>
          </View>
        </View>
        {childComments.length > 0 && (
          <View style={{marginLeft: 40}}>
            {childComments.map((child, idx) =>
              renderComment(child, level + 1, childComments, idx),
            )}
          </View>
        )}
      </View>
    );
  };

  const renderTimelineItem = ({item}: {item: TimelineItem}) => {
    if (item.type === 'activity') {
      const activity = item.data as ITaskActivities;
      return (
        <View style={{marginBottom: 16}}>
          <RenderHtml source={{html: getContentHistory(activity)}} baseFontStyle={{ color: 'black' }} />
          <TextCM>
            {DateUtils.convertDateToDDMMYYYY_H_M(activity.createdDate)}
          </TextCM>
        </View>
      );
    } else {
      const comment = item.data as IComment;
      return renderComment(comment, item.level || 0, [], 0);
    }
  };

  return (
    <View style={{backgroundColor: '#F2F5F8'}}>
      <View style={styles.ctnActivities}>
        <Icon name="activity" width={20} height={20} />
        <TextCM style={styles.ctnTextItem}>{t('HM.board.history')}</TextCM>
      </View>
      <KeyboardAwareFlatList
        scrollEnabled={false}
        contentContainerStyle={{
          paddingHorizontal: 26,
        }}
        data={getTimelineItems()}
        renderItem={renderTimelineItem}
        keyExtractor={(item, index) => `${item.type}-${item.data.id || index}`}
        enableOnAndroid={true}
      />
    </View>
  );
};

export default ActivitiesScreen;
