import {ScrollView, Text, View} from 'react-native';
import TextCM from '../../../components/Text';
import {BarChart} from 'react-native-gifted-charts';
import {styles} from './styles';
import {PriorityGroup} from '../../../../model/interface/dashboard.interface';
import {Font} from '../../../../constants';
import {useTranslation} from 'react-i18next';

type Props = {
  priority: PriorityGroup[];
};
const DashboardBarChart = ({priority}: Props) => {
  const {t} = useTranslation();

  const colorMap: {[key: string]: string} = {
    todo: '#00A3FF',
    processing: '#FF69B4',
    approved: '#943CDD',
    completed: '#90EE90',
  };
  const transformPriorityToStackData = (priorityData: PriorityGroup[]) => {
    const statusOrder = ['todo', 'approved', 'processing', 'completed'];
    try {
      const labelMap = {
        null: t('task.priority-null'),
        '1': t('task.priority-danger'),
        '2': t('task.priority-high'),
        '3': t('task.priority-medium'),
        '4': t('task.priority-low'),
      };
      const stackData = priorityData.map(item => {
        const label = labelMap[item.priority || 'null'];
        const taskStatusMap: {[key: string]: number} =
          item.taskCountStatus.reduce((acc, curr) => {
            acc[curr.status] = curr.taskCount;
            return acc;
          }, {} as {[key: string]: number});

        const stacks = statusOrder.map(status => {
          const value = taskStatusMap[status] || 0;
          return {value, color: colorMap[status]};
        });
        const totalValue = stacks.reduce((sum, stack) => sum + stack.value, 0);
        if (totalValue === 0) {
          stacks.push({value: 0, color: 'transparent'});
        }
        return {stacks, label};
      });
      return stackData;
    } catch (error) {
      console.error(error);
      return [];
    }
  };
  const prorityStackData = transformPriorityToStackData(priority);
  const renderDot = (color: string) => {
    return (
      <View
        style={{
          height: 10,
          width: 10,
          borderRadius: 1,
          backgroundColor: color,
          marginRight: 10,
        }}
      />
    );
  };
  const renderDescription = () => {
    return (
      <ScrollView horizontal style={{flexDirection: 'row', marginTop: 20}}>
        {Object.keys(colorMap).map(key => {
          return (
            <View
              key={key}
              style={{
                flexDirection: 'row',
                alignItems: 'center',
                padding: 5,
              }}>
              {renderDot(colorMap[key])}
              <Text
                style={{
                  color: colorMap[key],
                }}>
                {t(`HM.board.status-${key}`)}
              </Text>
            </View>
          );
        })}
      </ScrollView>
    );
  };
  return (
    <View style={styles.container}>
      <TextCM style={{fontSize: 16, fontFamily: Font.InterBold700}}>
        {t('task.priority-count')}
      </TextCM>
      <View>
        <BarChart
          stackData={prorityStackData}
          barWidth={45}
          spacing={25}
          noOfSections={4}
          yAxisTextStyle={styles.axisText}
          xAxisLabelTextStyle={styles.axisText}
          yAxisLabelSuffix=" "
          rulesType="dashed"
          rulesColor="#E0E0E0"
          showGradient={false}
          frontColor={'transparent'}
        />
      </View>
      {renderDescription()}
    </View>
  );
};

export default DashboardBarChart;
