import {Divider, Icon} from '@ui-kitten/components';
import {View, Pressable} from 'react-native';
import TextCM from '../../../../../../components/Text';
import React, {useEffect, useRef, useState} from 'react';
import WebView, {WebViewMessageEvent} from 'react-native-webview';
import {useBoardService} from '../../../../../../../hooks/apiHooks/useAPI';
import Toast from 'react-native-toast-message';
import {useTranslation} from 'react-i18next';
import {FormItem} from './helper';
import styles from './styles';
import {Color, String} from '../../../../../../../constants';
import ModalFullScreen from '../../../../../../components/ModalFullScreen';
import HeaderCM from '../../../../../../components/Header/HeaderCM';
import ButtonCM from '../../../../../../components/Button';
import {getConfig} from '../../../../../../../services/httpClient';
import FormAttach from '../modal-form';
import ModalConfirmCM from '../../../../../../components/ModalConfirm';
import GroupButtonCM from '../../../../../../components/GroupButton';
type Props = {
  taskId?: string;
};

const FormTask = ({taskId}: Props) => {
  const {t} = useTranslation();
  const BoardService = useBoardService();
  const webviewRef = useRef<WebView>(null);
  const [taskForm, setTaskForm] = useState<FormItem | null>(null);
  const [taskDataForm, setTaskDataForm] = useState<FormItem | null>(null);
  const [modalDetailForm, setModalDetailForm] = useState(false);
  const [confirmDeleteVisible, setConfirmDeleteVisible] = useState(false);
  const [modalForm, setModalForm] = useState(false);
  const getTaskForm = async (formId: string) => {
    try {
      const params = {versionId: formId};
      const data = await BoardService.getTaskFormData(params);
      if (data) {
        setTaskForm(data);
      }
    } catch (error) {
      console.log('error1', error);
      Toast.show({
        type: 'error',
        text1: 'Thông báo',
        text2: t('task.error-get-formtask'),
      });
    }
  };
  const getTaskFormId = async () => {
    try {
      if (!taskId) return;
      const data = await BoardService.getTaskFormId(taskId);
      if (data) {
        setTaskDataForm(data);
        return data;
      }
    } catch (error) {}
  };
  const onMessage = async (message: WebViewMessageEvent) => {
    const data = JSON.parse(message.nativeEvent.data);

    if (data?.result === 'e-from') {
      setTimeout(() => {
        patchValue();
      }, 300);
    } else if (data?.result === 'result') {
      const parsedForm = JSON.parse(taskDataForm?.jsonForm || '[]');
      const values = data?.data.map((item: any) => item.value);
      const updatedForm = parsedForm.map((item: any, index: number) => {
        const {id, ...rest} = item; // thay doi id thanh formId de cap nhat cho dung
        return {
          ...rest,
          formId: id,
          value: values[index] ?? '',
        };
      });

      const newJsonForm = JSON.stringify(updatedForm);
      const filteredFormData = {
        ...taskDataForm,
        jsonForm: newJsonForm,
      };
      const body = {
        ...filteredFormData,
        info: taskForm,
      };

      const updateFormTask = await BoardService.updateTaskFormData(body);
      if (updateFormTask) {
        setTaskDataForm(updateFormTask);
        setModalDetailForm(false);
        Toast.show({
          type: 'success',
          text1: t('CM.noti'),
          text2: t('task.update-formtask-success'),
        });
      }
    }
  };
  const patchValue = async () => {
    if (taskDataForm?.jsonForm) {
      const dataFrom = JSON.parse(taskDataForm?.jsonForm || '[]').filter(
        (d: any) => d.value,
      );
      const formData = JSON.stringify({
        type: 'postFormEdit',
        isReadonly: false,
        data: dataFrom,
      });
      const scriptJSX = `window.postMessage('${formData
        .replace(/\\/g, '\\\\')
        .replace(/'/g, "\\'")}', '*');`;
      webviewRef?.current?.injectJavaScript(scriptJSX);
    }
  };
  const handleSaveInfoAndSubmit = () => {
    const dataSubmit = JSON.stringify({
      result: 'submit',
    });
    const scriptJSX = `window.postMessage('${dataSubmit}', '*');`;
    webviewRef?.current?.injectJavaScript(scriptJSX);
  };
  const handleAddTasKForm = async (formData: FormItem) => {
    const body = {
      jsonForm: formData.jsonForm,
      formId: formData.versionId,
      resourceId: taskId,
    };
    if (!taskForm) {
      const added = await BoardService.addTaskFormData(body);
      if (added) {
        await getTaskForm(formData.versionId);
        setTaskDataForm(added);
      }
      return;
    }
    const filteredFormData = {
      ...taskDataForm,
      jsonForm: formData.jsonForm,
      formId: formData.versionId,
    };
    const bodyUpdate = {
      ...filteredFormData,
      info: taskForm,
    };
    const updated = await BoardService.updateTaskFormData(bodyUpdate);

    if (updated) {
      await getTaskForm(formData.versionId); // dùng formId mới
      setTaskDataForm(updated); // cập nhật lại dữ liệu form
    }
  };
  const handleConfirmDelete = async () => {
    try {
      if (taskDataForm?.id) {
        const res = await BoardService.deleteTaskFormById(taskDataForm.id);
        if (res) {
          setConfirmDeleteVisible(false);
          setTaskForm(null);
          setTaskDataForm(null);
          Toast.show({
            type: 'success',
            text1: t('CM.noti'),
            text2: t('task.delete-formtask-success'),
          });
        } else {
          console.log('Xóa thất bại, phản hồi không mong đợi:', res);
        }
      }
    } catch (error) {
      console.log('Delete error:', error);
    }
  };
  useEffect(() => {
    const fetchData = async () => {
      const formIdData = await getTaskFormId();
      if (formIdData?.formId) {
        await getTaskForm(formIdData.formId);
      }
    };

    fetchData();
  }, []);

  return (
    <View>
      <View
        style={{
          ...styles.ctnTaskDate,
          alignItems: 'center',
        }}>
        <Icon name="attach-2-outline" width={20} height={20} />
        <View style={styles.ctnSubTask}>
          <TextCM style={styles.ctnTextItem}>Biểu mẫu đính kèm</TextCM>
        </View>
      </View>
      <View style={styles.addForm}>
        {taskForm ? (
          <View style={styles.ctnSubTask}>
            <Pressable
              onPress={() => {
                setModalDetailForm(true);
              }}>
              <TextCM style={{color: Color.primary01}}>
                {taskForm.formName}
              </TextCM>
            </Pressable>
            <View style={styles.ctnIconForm}>
              <Pressable onPress={() => setModalForm(true)}>
                <Icon name="edit-2-outline" width={20} height={20} />
              </Pressable>
              <Pressable onPress={() => setConfirmDeleteVisible(true)}>
                <Icon name="trash-outline" width={20} height={20} />
              </Pressable>
            </View>
          </View>
        ) : (
          <Pressable onPress={() => setModalForm(true)}>
            <TextCM style={{color: Color.primary01}}>
              {t('task.formtask-placeholder-1')}
            </TextCM>
          </Pressable>
        )}
      </View>
      <ModalFullScreen
        isVisible={modalForm}
        children={
          <FormAttach
            handleSubmitData={handleAddTasKForm}
            onClose={() => setModalForm(false)}
            selectedFormId={taskForm?.formId}
          />
        }
      />
      <ModalFullScreen
        isVisible={modalDetailForm}
        children={
          <View style={{flex: 1}}>
            <HeaderCM
              style={{backgroundColor: '#fff'}}
              contentStyle={{backgroundColor: '#fff'}}
              titleStyle={{color: '#000810'}}
              fillIconBackLeft="#000810"
              onPressIconLeft={() => {
                setModalDetailForm(false);
              }}
              title={`Biểu mẫu "${taskForm?.formName}"`}
              alignment="start"
             
            />
            <Divider />
            <WebView
              nestedScrollEnabled={true}
              ref={webviewRef}
              startInLoadingState
              onMessage={onMessage}
              javaScriptEnabled
              injectedJavaScript={String.SCRIPT_SCALE_WEBVIEW}
              allowsInlineMediaPlayback={true}
              thirdPartyCookiesEnabled={true}
              sharedCookiesEnabled={true}
              mediaPlaybackRequiresUserAction={false}
              webviewDebuggingEnabled
              source={{
                uri: getConfig().BASE_URL_FORM + taskDataForm?.formId,
              }}
            />
            <View
        style={{
          marginBottom: 12,
        }}>
        <GroupButtonCM
          containerStyle={styles.groupBtn}
          labelLeft={t('CM.labelCancel')}
          labelRight={t('CM.confirm')}
          onPressLeft={() => setModalDetailForm(false)}
          onPressRight={handleSaveInfoAndSubmit}
        />
      </View>
          </View>
        }
      />
      <ModalConfirmCM
        type="cancel"
        isVisible={confirmDeleteVisible}
        onClose={() => setConfirmDeleteVisible(false)}
        title={t('task.delete-formtask-confirm')}
        content={t('task.delete-formtask-confirm-1')}
        onConfirm={handleConfirmDelete}
        styleBtnRight={{backgroundColor: Color.RedE14337}}
        labelCancel="Hủy"
        labelConfirm="Xác nhận"
      />
    </View>
  );
};

export default FormTask;
